import pandas as pd

def clean(df):
    df = df.copy()
    # Standardise categorical labels
    if 'species' in df.columns:
        df['species'] = df['species'].astype(str).str.strip().str.title()
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip().str.title()
    # Convert body_mass_g from text (commas) to numeric
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = (
            df['body_mass_g']
            .astype(str)
            .str.replace(',', '', regex=False)
            .astype(float)
        )
    # Ensure flipper_length_mm is numeric (it may be stored as text)
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    # Compute average body mass per sex, ignoring unknown sex
    grp = df.dropna(subset=['sex']).groupby('sex')['body_mass_g'].mean()
    return {sex: float(val) for sex, val in grp.items()}
